@orders_bp.route("/report", methods=["GET"])
def orders_report():
    key = get_api_key()
    if key is None:
        return jsonify({"error": "valid API key required"}), 401
    session = get_session()
    orders = session.query(Order).all()
    return jsonify({"order_count": len(orders), "revenue": sum(o.total for o in orders), "orders": [o.to_dict() for o in orders]})

def get_api_key() -> ApiKey | None:
    raw = request.headers.get("X-Api-Key", "")
    if not raw:
        return None
    session = get_session()
    return session.query(ApiKey).filter(ApiKey.key == raw).first()

def require_api_key_scope(required_scope: str):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            key = get_api_key()
            if key is None:
                return jsonify({"error": "valid API key required"}), 401
            if key.scope != required_scope:
                return jsonify({"error": "API key lacks required scope"}), 403
            g.api_key = key
            return fn(*args, **kwargs)
        return wrapper
    return decorator

class ApiKey(Base):
    ...
    scope = Column(String(50), nullable=False, default="orders:read")

